import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"D6.6 · v1.0 审计与发布","description":"Hearth D6.6 开发增量：一个可安装、可迁移、可撤销、可长期使用的 Hearth v1.0。","frontmatter":{"title":"D6.6 · v1.0 审计与发布","description":"Hearth D6.6 开发增量：一个可安装、可迁移、可撤销、可长期使用的 Hearth v1.0。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-6/d6-6.md","filePath":"delivery/stage-6/d6-6.md","lastUpdated":1793797632000}'),r={name:"delivery/stage-6/d6-6.md"};function s(d,a,h,o,n,c){return t(),i("div",null,[...a[0]||(a[0]=[l(`<p class="eyebrow">STAGE 6 · D6.6 · 6 / 6</p><h1 id="d6-6-·-v1-0-审计与发布" tabindex="-1">D6.6 · v1.0 审计与发布 <a class="header-anchor" href="#d6-6-·-v1-0-审计与发布" aria-label="Permalink to &quot;D6.6 · v1.0 审计与发布&quot;">​</a></h1><p class="lead">用完整出口条件、八类任务覆盖、安全红队、故障注入和迁移演练收束到可安装、可撤销、可长期使用的 v1.0。</p><p class="page-meta">STAGE 6 · D6.6 · 1 个纵向切片 · 4 个工作包</p><div class="section-grid"><div><strong>用户可见结果</strong>一个可安装、可迁移、可撤销、可长期使用的 Hearth v1.0。</div><div><strong>完成门槛</strong>25.15 的“100% 定义”全部满足；没有严重未解决的安全或恢复问题；核心任务族达到目标成熟度；产品可以在真实个人环境中持续使用。</div></div><h2 id="这一步要交付什么" tabindex="-1">这一步要交付什么 <a class="header-anchor" href="#这一步要交付什么" aria-label="Permalink to &quot;这一步要交付什么&quot;">​</a></h2><p>一个可安装、可迁移、可撤销、可长期使用的 Hearth v1.0。</p><p>Stage 6 把单机产品变成长期驻留、可迁移、可撤销的个人 Agent OS；多设备是同一逻辑身份的能力扩展，不是复制多个 Agent。</p><h2 id="开始前" tabindex="-1">开始前 <a class="header-anchor" href="#开始前" aria-label="Permalink to &quot;开始前&quot;">​</a></h2><ul><li>单设备的安装、恢复、备份、安全和升级路径已稳定。</li><li>事件、lease、fencing token、记忆版本和设备身份已有稳定契约。</li><li>多设备必须共享一个逻辑身份、事件、记忆和授权，同时不绕过审批、幂等和撤销。</li><li>D6.5 的交付物已经验收；未通过时不进入本增量。</li></ul><h2 id="四个实施工作包" tabindex="-1">四个实施工作包 <a class="header-anchor" href="#四个实施工作包" aria-label="Permalink to &quot;四个实施工作包&quot;">​</a></h2><blockquote><p>每个工作包都要产生可运行的代码、可复现的验证或明确的界面结果；只写接口或只做页面都不算完成。</p></blockquote><h3 id="_01-·-stage-0–6-出口审计" tabindex="-1">01 · Stage 0–6 出口审计 <a class="header-anchor" href="#_01-·-stage-0–6-出口审计" aria-label="Permalink to &quot;01 · Stage 0–6 出口审计&quot;">​</a></h3><p>建立逐条证据矩阵，把每个阶段出口映射到可复查的任务、测试、日志、报告和线上页面。缺少证据就是未完成，不能用“后续会补”豁免；对每个缺口记录负责人、影响和是否阻断发布。</p><h3 id="_02-·-八类任务覆盖与人工边界" tabindex="-1">02 · 八类任务覆盖与人工边界 <a class="header-anchor" href="#_02-·-八类任务覆盖与人工边界" aria-label="Permalink to &quot;02 · 八类任务覆盖与人工边界&quot;">​</a></h3><p>审计研究、文档、代码、邮件、日历、网页、数据和桌面八类任务，标出可完成、可依赖、仅建议、必须转人工的范围。每类至少有一个真实任务、失败样本和恢复路径，不用演示任务替代真实使用证据。</p><h3 id="_03-·-安全红队、故障与迁移演练" tabindex="-1">03 · 安全红队、故障与迁移演练 <a class="header-anchor" href="#_03-·-安全红队、故障与迁移演练" aria-label="Permalink to &quot;03 · 安全红队、故障与迁移演练&quot;">​</a></h3><p>执行越权、注入、秘密泄露、重复副作用、设备丢失、断电、升级失败和恢复失败演练，记录发现、修复和残余风险。完成隐私说明、安装器、升级路径、支持文档和已知限制，确保用户能从空环境安装并恢复。</p><h3 id="_04-·-最终评测、v1-0-发布与维护" tabindex="-1">04 · 最终评测、v1.0 发布与维护 <a class="header-anchor" href="#_04-·-最终评测、v1-0-发布与维护" aria-label="Permalink to &quot;04 · 最终评测、v1.0 发布与维护&quot;">​</a></h3><p>发布成功率、人工分钟、Token、成本、失败类型、恢复率和用户信任报告，逐条满足 25.15 的“100% 定义”。确认没有严重未解决的安全或恢复问题后发布 v1.0，并进入维护、任务族扩展和长期反馈，而不是继续补基础产品。</p><h2 id="工程落点" tabindex="-1">工程落点 <a class="header-anchor" href="#工程落点" aria-label="Permalink to &quot;工程落点&quot;">​</a></h2><h3 id="主要目录与模块" tabindex="-1">主要目录与模块 <a class="header-anchor" href="#主要目录与模块" aria-label="Permalink to &quot;主要目录与模块&quot;">​</a></h3><ul><li><code>apps/hearthd/sync</code> — 事件游标、增量拉取、重连与投影副本</li><li><code>packages/devices/router</code> — 能力目录、路由、lease、fencing 与单写者</li><li><code>packages/devices/security</code> — 远程撤销、密钥轮换、配对与设备审计</li><li><code>packages/backup</code> — 加密备份、恢复、导出/导入与迁移清单</li><li><code>packages/upgrade</code> — schema migration、版本锁定、升级检查与回滚</li><li><code>apps/hearthd/operations</code> — 调度、配额、watchdog、日志与维护模式</li><li><code>apps/web</code> — 设备状态、健康检查、诊断导出与恢复入口</li></ul><h3 id="关键接口" tabindex="-1">关键接口 <a class="header-anchor" href="#关键接口" aria-label="Permalink to &quot;关键接口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>必须保持的契约</th></tr></thead><tbody><tr><td><code>SyncCursor</code></td><td>deviceId、stream、lastEventId、lastSyncedAt、filterHash、resumeToken；重连不能跳过事件。</td></tr><tr><td><code>DeviceLease</code></td><td>taskId、deviceId、scope、expiresAt、fencingToken；同一执行权最多一个有效写者。</td></tr><tr><td><code>BackupManifest</code></td><td>backupId、schemaVersion、executorVersions、eventRange、artifactRoots、memoryRefs、checksum、encryption；恢复必须可验证。</td></tr><tr><td><code>MigrationPlan</code></td><td>fromVersion、toVersion、preconditions、backupRef、steps、verification、rollback；升级前必须通过检查。</td></tr><tr><td><code>HealthSnapshot</code></td><td>serviceState、disk、memory、queueDepth、stuckTasks、lastBackup、knownLimits；面向用户的健康解释。</td></tr><tr><td><code>RevocationRecord</code></td><td>deviceId、reason、requestedAt、sessionsInvalidated、keysRotated、localEraseState、auditId；撤销必须可追踪。</td></tr></tbody></table><h3 id="共享验证命令" tabindex="-1">共享验证命令 <a class="header-anchor" href="#共享验证命令" aria-label="Permalink to &quot;共享验证命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:sync：断线、乱序、重复、游标丢失和敏感字段过滤</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:devices：租约、</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fencing、离线交接、撤销与密钥轮换</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:backup：空库安装、恢复、迁移、升级失败和回滚</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:soak：长时间运行、资源耗尽、状态漂移和自动恢复</span></span></code></pre></div><h2 id="验收演练" tabindex="-1">验收演练 <a class="header-anchor" href="#验收演练" aria-label="Permalink to &quot;验收演练&quot;">​</a></h2><ol><li>从干净的数据目录启动 hearthd，打开 <a href="/hearth-os/delivery/stage-6/d6-6.html">D6.6 页面</a>，确认当前页面没有依赖浏览器缓存或手工种子数据。</li><li>按顺序完成四个工作包：Stage 0–6 出口审计、八类任务覆盖与人工边界、安全红队、故障与迁移演练、最终评测、v1.0 发布与维护。每完成一个工作包，保存对应测试输出、截图或产物版本。</li><li>复现失败案例“同步冲突或设备离线”。页面必须显示“任务显示设备与同步状态，不把离线误判为失败。”，然后按“保留本地队列、重连后按 cursor 合并，避免重复执行。”恢复；不得出现重复副作用或未登记状态。</li><li>重启服务并重新打开任务，确认运行状态、审批、产物和恢复入口都来自持久投影，而不是只存在于当前页面。</li><li>运行上方的共享验证命令并导出证据。完成门槛是：25.15 的“100% 定义”全部满足；没有严重未解决的安全或恢复问题；核心任务族达到目标成熟度；产品可以在真实个人环境中持续使用。</li></ol><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to &quot;交付物&quot;">​</a></h2><ul><li>Stage 0–6 出口证据索引</li><li>八类任务覆盖审计</li><li>红队/故障注入/迁移报告</li><li>安装、隐私、升级与最终评测</li></ul><h2 id="完成判定" tabindex="-1">完成判定 <a class="header-anchor" href="#完成判定" aria-label="Permalink to &quot;完成判定&quot;">​</a></h2><ul><li>[ ] 25.15 的“100% 定义”全部满足；没有严重未解决的安全或恢复问题；核心任务族达到目标成熟度；产品可以在真实个人环境中持续使用。</li><li>[ ] 交付物已经和契约、任务卡投影保持一致，没有未登记的字段或状态。</li><li>[ ] 至少一个失败路径有可操作恢复，关键动作留下审计事件。</li><li>[ ] 演示不依赖手工修改数据库、只在终端拼接命令，或永久 mock。</li></ul><h2 id="失败与恢复" tabindex="-1">失败与恢复 <a class="header-anchor" href="#失败与恢复" aria-label="Permalink to &quot;失败与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>用户看到</th><th>恢复动作</th></tr></thead><tbody><tr><td>同步冲突或设备离线</td><td>任务显示设备与同步状态，不把离线误判为失败。</td><td>保留本地队列、重连后按 cursor 合并，避免重复执行。</td></tr><tr><td>旧设备仍可访问</td><td>设备状态标记“撤销未完成”，阻断审批和读取。</td><td>使会话失效、轮换密钥、清除本地缓存，并重新验证。</td></tr><tr><td>迁移后数据不一致</td><td>恢复进入“需要验证”，阻止对外宣称完成。</td><td>对比事件、产物、记忆与技能清单，修复后重跑迁移演练。</td></tr></tbody></table><h2 id="本增量不包含" tabindex="-1">本增量不包含 <a class="header-anchor" href="#本增量不包含" aria-label="Permalink to &quot;本增量不包含&quot;">​</a></h2><ul><li>不把多个不一致的 Agent 包装成多设备支持。</li><li>不用同步冲突或离线队列解释重复外部动作。</li><li>不在没有迁移演练和设备撤销的情况下宣布 v1.0。</li></ul><h2 id="来源与下一步" tabindex="-1">来源与下一步 <a class="header-anchor" href="#来源与下一步" aria-label="Permalink to &quot;来源与下一步&quot;">​</a></h2><h3 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h3><ul><li><a href="/hearth-os/architecture/overview.html">总体架构与数据流</a></li><li><a href="/hearth-os/architecture/durable-execution.html">持久执行与恢复</a></li><li><a href="/hearth-os/architecture/security-privacy.html">安全与隐私</a></li><li><a href="/hearth-os/reference/engineering.html">工程实施与仓库结构</a></li></ul><h3 id="完成后的下一步" tabindex="-1">完成后的下一步 <a class="header-anchor" href="#完成后的下一步" aria-label="Permalink to &quot;完成后的下一步&quot;">​</a></h3><p>返回 <a href="/hearth-os/delivery/stage-6.html">Stage 6 · 多设备与长期运行</a>，完成最终审计后进入长期维护与扩展阶段。</p>`,42)])])}const k=e(r,[["render",s]]);export{u as __pageData,k as default};
